INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Bunny: First Blood', 'Don''t let the ears fool you, this is no cuddly pet rabbit. Bloody Bunny is armed, she''s dangerous and she''ll stop at nothing to get her revenge. Master the one-touch controls to embark on a brutal, bloody, rhythmic rampage, slicing and dicing your way through Bunny''s world, from Master Sloth''s zen garden to the mysterious mechanical lair. Slay your way through the zombie mice minions using all your ninja skills to get to the big, scary evil bosses.' FROM games WHERE igdb_id = 175386 ON CONFLICT (game_id, language_code) DO NOTHING;
