INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garrison Gauntlet', 'Garrison Gauntlet is an oldschool-style action-platformer where you play through over four stages of intense challenges! A little robot that is to serve as nothing more than as one of the many robotic minions owned by the evil tyrant, Garrison, it realizes that being in such a position is no rewarding task. As the robot itself, you must stop Garrison''s forces from the inside before they take over the world!' FROM games WHERE igdb_id = 108017 ON CONFLICT (game_id, language_code) DO NOTHING;
