INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Subwords', 'Subwords is an exciting mix between a trivia and a word game. Words are split into syllables and you have to put them back together as fast as possible. The words in every level are bound to a certain topic, so you have to know about the topic to solve it. But it''s no problem if you aren''t that familiar with a specific topic: Simply click the bulb to learn something new!' FROM games WHERE igdb_id = 173801 ON CONFLICT (game_id, language_code) DO NOTHING;
