INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Monster', '《清》是一款具有惊悚和压抑元素的像素画风角色扮演类游戏。某天深夜，家中突然发生了奇怪的异变，家人的离奇惨死、若隐若现的鬼影……这些仿佛都和失踪已久的双胞胎中的清有关。主角为了调查事情的真相，陷入了恐惧和回忆之中。' FROM games WHERE igdb_id = 111019 ON CONFLICT (game_id, language_code) DO NOTHING;
