INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whirlygig', 'Whirlygig is a block building game which consists of 4 unique grids - Fall, Winter, Spring, and Summer. Blocks move upward in Fall, to the right in Winter, downward in Spring, and to the left in Summer. Every 5 turns, a new grid is randomly selected as the next grid to play in. Game level, speed, and scores increase as you destroy more rows of blocks. Build and destroy until the Whirlygig becomes too fast to handle.' FROM games WHERE igdb_id = 105178 ON CONFLICT (game_id, language_code) DO NOTHING;
