INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'System Syzygy', 'System Syzygy is a story and a puzzle game, in the style of Cliff Johnson''s classic Macintosh games The Fool''s Errand and 3 in Three, and of Andrew Plotkin''s System''s Twilight. As you move through the game, solving a variety of different kinds of puzzles, the game tells the story a piece at a time. By the end of the game, all the different puzzles and pieces of the story come together into a single meta-puzzle.' FROM games WHERE igdb_id = 252684 ON CONFLICT (game_id, language_code) DO NOTHING;
