INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disenchantment Nirvana', '祛魅·入灭（祛魅2）是一款小清新像素风回合制角色扮演游戏，是祛魅系列历代作品中最好的一款。剧情发生在一代教化事件结束三个月后的极北之地，玩家将体验主角月泷烟的爱情与复仇，领略步步走向灭亡的不归路。' FROM games WHERE igdb_id = 111776 ON CONFLICT (game_id, language_code) DO NOTHING;
