INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block-a-Pix Color', 'Reveal the picture by dividing the grid into smaller rectangular blocks. Each block must contain one clue number, which tells you the number of grid squares covered by that block and the color the block will be painted. Block-a-Pix can always be solved using logic and deduction. You don''t ever have to guess! This game contains 120 exclusive puzzles, designed by Conceptis Ltd. Puzzles range in difficulty and size from small introductory pictures to huge scrollable grids with highly detailed pictures.' FROM games WHERE igdb_id = 102329 ON CONFLICT (game_id, language_code) DO NOTHING;
