INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ergastulum', 'Ergastulum is a first-person fantasy horror adventure game that blends a mix of Asian and Western folklore to create a terrifying vision that will test a players faith to the extremes. The game focuses on psychological horror which relies on the character’s fears and abnormal psyche to frighten players. How far will you go in rediscovering your lost faith?' FROM games WHERE igdb_id = 75580 ON CONFLICT (game_id, language_code) DO NOTHING;
