INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spice Pirates in Space: A Retro RPG', 'Embark on a thrilling adventure aboard the Cool Ship while you try to stop an evil Space Wizard from destroying the galaxy. Visit "amazing" planets, argue with NPC''s, find items to help you on your quest, and roll dice that are based on your upgradeable stats. Yeah, it''s that kind of game.' FROM games WHERE igdb_id = 112623 ON CONFLICT (game_id, language_code) DO NOTHING;
