INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escort Yourself Out', 'Escort Yourself Out is an escort-mission-style game in which you are asked to help your childhood self navigate triggering environments. While moving through everyday spaces fraught with triggers, you must take action to care for yourself in order to navigate the situation. It is an autobiographical representation of some of my experiences being mentally ill.' FROM games WHERE igdb_id = 134962 ON CONFLICT (game_id, language_code) DO NOTHING;
