INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kodamachi', 'Kodamachi is a 2D arcade platformer where you can’t jump so carelessly. With a platform changing mechanic that lets your discover new paths, quirky NPCs, and a retro arcade aesthetic, play through a delightful short story as you swiftly drift atop the brilliantly lit rooftops of a Japanese city.' FROM games WHERE igdb_id = 262022 ON CONFLICT (game_id, language_code) DO NOTHING;
