INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('oil', 96192, '2018-04-04', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sce4ta.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oil', 'Oil is a game about digging for oil in early 1900s America. It’s a two player game that you play against a computer player or with your friend on the same device. OIL is a tense digital board game that plays a lot like battleships with a major oil mining twist! Unlike battleships, in OIL you and your opponent share the same play-space and compete for the same oil. Use your strategic mastery to beat your opponent and show who is the best oil miner! Influenced by the film ‘There Will Be Blood’, OIL focuses on the competition of oil mining in the iconic setting of the American oil boom of the early 1900s.' FROM games WHERE igdb_id = 96192 ON CONFLICT (game_id, language_code) DO NOTHING;
