INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block Smashers', 'Block Smashers is physics based VR puzzle game where you throw balls at structures to collect crystals. You collect crystals by either hitting them directly or taking out the supports holding them up. The goal is to get all the crystals on each level with as few throws as possible. There are three tiers of rewards: Gold, Silver, and Bronze based on the number of throws you take to collect all the crystals.' FROM games WHERE igdb_id = 96473 ON CONFLICT (game_id, language_code) DO NOTHING;
