INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kemono Friends Pavilion', 'This game puts a Kemono Friends spin on Neko Atsume. Players leave out toys and Japari Buns to attract Friends. The player doesn''t directly interact with the Friends when they visit, but can watch them while they play and receive gifts of Pikapika crystals when they leave. Crystals can be spent on new toys or fancier Japari Buns. In addition, the player can complete various challenges by observing special events in-game; witnessing these requires the player to attract particular combinations of Friends to the park at once.' FROM games WHERE igdb_id = 214738 ON CONFLICT (game_id, language_code) DO NOTHING;
