INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.F.R.: The Light VR', 'Unprepared and helpless, you are taken to a dark place where a mysterious light hunts you. In this relentlessly terrifying survival horror game, you must use your wits to stay alive and extinguish the light, or perish trying. But be warned: the light is crafty and observant, so this won''t be easy.' FROM games WHERE igdb_id = 100353 ON CONFLICT (game_id, language_code) DO NOTHING;
