INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('balloon-trip--1', 269167, '2018-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co75jz.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Balloon Trip', 'You''re floating high above the majestic ocean, held aloft by balloons as you gaze your surroundings. But this is no ordinary, leisurely flight! Your goal in Balloon Trip is to collect as many balloons as possible, all the while avoiding electric sparks that will pop your balloons and bring a tragic end to your journey! And if the sparks didn''t provide enough danger for you, the water below is also treacherous, full of aggressive fish that will leap into the air to pull you into the murky depths below! So be sure you keep an adequate distance between you and the water, as you don''t want to become fish food!
