INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jump Squad', 'Collect coins, bop enemies’ heads, and leap over mushrooms in Jump Squad, a fun and cute casual game. Enjoy its easy-to-learn gameplay as you journey through different areas, jumping and spinning with your own personalized squad of cats and dogs! Once you’ve had enough of jumping, why not raise the stakes for more coins by playing the Higher or Lower mini-game? Who knows, your squad could be millionaires in no time!' FROM games WHERE igdb_id = 218412 ON CONFLICT (game_id, language_code) DO NOTHING;
