INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Handful of Keflings', 'The Keflings need your help! Visit a magical realm and lend the tiny Keflings a hand. Start by building a single home and work towards creating a thriving bastion of culture sure to be the envy of cultural bastions everywhere! Put the cheerful Keflings to work harvesting and refining resources while you unlock the blueprints and building pieces used to make buildings like a lumber mill or Magic Mark''s Mutton Masseuse. Do it all in this friendly, laid-back city building game with heart.' FROM games WHERE igdb_id = 83948 ON CONFLICT (game_id, language_code) DO NOTHING;
