INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Travel Mosaics 5: Waltzing Vienna', 'This time, join the Walker family on their sight-seeing tour to the most outstanding and famous attractions in Vienna. Explore the legendary cultural legacy of Austrian capital: learn interesting facts about the city and its inhabitants, answer tricky trivia questions and as always - solve gorgeous nonograms! Travel Mosaics is a nonogram-picross puzzle series that takes you all around the world! Each puzzle is handcrafted and features a recognizable picture that is revealed as you play. Sit back, relax and have fun: players of all ages are welcome!' FROM games WHERE igdb_id = 147088 ON CONFLICT (game_id, language_code) DO NOTHING;
