INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess Sudoku', 'Welcome! Are you ready for a new challenge, a new puzzle game? This is Chess inside a Sudoku! Well kind of... the rules of Chess aren''t taken very seriously. But you do need some strategy like in Chess and you are solving a Sudoku, so the title isn''t lying!' FROM games WHERE igdb_id = 100649 ON CONFLICT (game_id, language_code) DO NOTHING;
