INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FriendZoned Archer', 'FriendZoned Archer is an action adventure game inspired by the classic NES Zelda. There is complete freedom of exploration, hidden Areas, hidden dungeons and key items to help you ease through the open world. The combat focuses on shooting and combos and the key items can interact with enemies, world and bosses thus drawing inspirations from the sandbox nature of open world games.' FROM games WHERE igdb_id = 88132 ON CONFLICT (game_id, language_code) DO NOTHING;
