INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baseball Mogul 2018', 'Baseball Mogul is designed to help you manage your team over many simulated years. Manage your team one day at a time, or let the computer simulate weeks or months at a stretch so you can play for virtual years or decades. As your players age, their abilities mature and decline realistically. Don''t forget to build your team for the long term, rather than spending all your money on free agents this season.' FROM games WHERE igdb_id = 99042 ON CONFLICT (game_id, language_code) DO NOTHING;
