INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Sixed', 'Deep Sixed is a roguelike space sim that will force you to use strategy, ingenuity and duct tape to keep your ship (and your skull) in one piece as you risk exploring a mysterious nebula protected by dangerous alien creatures.' FROM games WHERE igdb_id = 29504 ON CONFLICT (game_id, language_code) DO NOTHING;
