INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dodge Club Pocket', 'The underground ravers of Dodge Club invite YOU to play in their pixel dance party. Dodge the red hot fireball and electric spark in a variety of unique minigame challenges, each one more wild than the last! As you play, you''ll even unlock mysterious bonus content in the form of "presents", including new characters, comics by Linzb0t, extra music, and more. Speck and her raver friends can''t wait to meet you, so join the club now on your Nintendo 3DS with Dodge Club Pocket!' FROM games WHERE igdb_id = 96105 ON CONFLICT (game_id, language_code) DO NOTHING;
