INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brass Tactics', 'Brass Tactics is a real-time strategy (RTS) game designed exclusively for virtual reality (VR), developed by Hidden Path Entertainment. Set in a steampunk-inspired world, players command massive armies from a tabletop-style battlefield, using intuitive hand gestures to deploy troops, build structures, and execute tactical maneuvers.
