INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defend the Cake Tower Defense', 'From a team of Blizzard & Riot alumni comes the most delicious tower defense game! Help Eggperor Shellemane and the Eggbirds keep their cakes safe from an onslaught of persistent insects. The game begins when you place your tasty cake castle on the map. Choose carefully, there are armies of ants on their way to steal a slice! After that, it’s time to plan your strategy. Build your maze to outsmart the mischievous ants and protect your prized cake. Use watermelon slingshots and frosting guns to thwart the onslaught of bees, rocket snails, and ants on scooters!' FROM games WHERE igdb_id = 175173 ON CONFLICT (game_id, language_code) DO NOTHING;
