INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candies ''N Curses', 'Candies ''n Curses is a 2D arcade rogue-lite game, featuring chaotic ''sugar-rushed'' ghost slaying. Play as Molli Pop as you fend off hordes of adorable ghosts and take down mischievous bosses, all within the cursed walls of a twisted mansion. Power-up with new flashlights and abilities as you level up - and join forces with ghostly pups and other spectral creatures as you work together to purge the mansion of its ghostly residents.' FROM games WHERE igdb_id = 112174 ON CONFLICT (game_id, language_code) DO NOTHING;
