INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Martha Madison: Forces', 'Can you help the penguins in their quest for ice bricks? In Martha Madison: Forces, students use forces, acceleration, inertia, and friction to move giant ice blocks across a frozen landscape. Once the correct forces are applied, ice choppers are put to work, breaking the blocks into small bricks that Martha’s penguin friends need to build new homes. Experience a free-play forces playground and create custom, playable levels in the game!' FROM games WHERE igdb_id = 83956 ON CONFLICT (game_id, language_code) DO NOTHING;
