INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grim Soul: Dark Fantasy Survival', 'In Grim Soul you have to fight in the Empire''s lands affected by unknown disease. Peasants lost their minds, knights surrendered to plague in exchange for incredible power. Surviving until morning gets harder each and every day as the province is flooded with terror. But darkness cannot win whilst you''re holding your sword. Get a hidden reward, build your own castle, reveal mysteries of the disaster and, most importantly, survive at any cost!' FROM games WHERE igdb_id = 109131 ON CONFLICT (game_id, language_code) DO NOTHING;
